/**
 * Slate Light: Cloud9 editor theme in the colours of the slate-light skin, whose
 * default editor theme it is (plugins/c9.ide.theme.slate/plugin.js).
 * See slate-light.css, generated by tools/gen-themes.js.
 */
define(function(require, exports, module) {

exports.isDark = false;
exports.cssClass = "ace-slate-light";
exports.cssText = require("text!./slate-light.css");

var dom = require("ace/lib/dom");
dom.importCssString(exports.cssText, exports.cssClass);
});
